g.script:
struct Inputs {
  time: f32,
  resolution: vec2f,
  storm: f32,
  ground: vec3f,
  calmA: vec3f,
  calmB: vec3f,
  stormA: vec3f,
  stormB: vec3f,
}

fn hash(p: vec2f) -> f32 {
  return fract((sin(dot(p, vec2f(127.0999984741211, 311.70001220703125))) * 43758.5453f));
}

fn noise(p: vec2f) -> f32 {
  let cell = floor(p);
  let f = fract(p);
  let u = ((f * f) * (vec2f(3) - (f * 2f)));
  let a = hash(cell);
  let b = hash((cell + vec2f(1, 0)));
  let c = hash((cell + vec2f(0, 1)));
  let e = hash((cell + vec2f(1)));
  return mix(mix(a, b, u.x), mix(c, e, u.x), u.y);
}

fn fbm(start: vec2f) -> f32 {
  var p = start;
  var sum = 0f;
  var weight = 0.5f;
  for (var octave = 0; (octave < 5i); octave++) {
    sum += (weight * noise(p));
    p = (p * 2.03f);
    weight *= 0.5f;
  }
  return sum;
}

fn shade(uv: vec2f, input: Inputs) -> vec4f {
  let s = input.storm;
  let t = (input.time * mix(0.12f, 0.55f, s));
  let p = vec2f(((uv.x * input.resolution.x) / input.resolution.y), uv.y);
  let scale = mix(1.3f, 2.4f, s);
  let q = vec2f(fbm(((p * scale) + vec2f((t * 0.6f), 0f))), fbm(((p * scale) + vec2f(5.2f, (1.3f - (t * 0.5f))))));
  let n = fbm((((p * scale) + (q * mix(1.2f, 3.2f, s))) + vec2f(t, (-(t) * 0.4f))));
  let bend = ((n - 0.5f) * mix(0.7f, 1.1f, s));
  let ribbon = exp(-(pow((((uv.y - 0.55f) - bend) * mix(5f, 3.2f, s)), 2f)));
  let second = (exp(-(pow((((uv.y - 0.3f) + (bend * 0.6f)) * mix(9f, 5f, s)), 2f))) * 0.55f);
  let streaks = (smoothstep(0.58f, 0.85f, n) * s);
  let flicker = (1f + ((s * 0.2f) * sin(((input.time * 11f) + (p.x * 9f)))));
  let a = mix(input.calmA, input.stormA, s);
  let b = mix(input.calmB, input.stormB, s);
  let band = mix(a, b, clamp(((n * 1.4f) - 0.2f), 0f, 1f));
  let glow = clamp((((((ribbon + second) * flicker) * 0.85f) + (n * 0.25f)) + (streaks * 0.7f)), 0f, 1f);
  let edge = smoothstep(0f, 0.12f, min(uv.x, (1f - uv.x)));
  return vec4f(mix(input.ground, band, (glow * edge)), 1f);
}
@group(0) @binding(0) var<uniform> svjeez_inputs: Inputs;

struct SvjeezVarying {
  @builtin(position) position: vec4f,
  @location(0) uv: vec2f,
}

@vertex fn svjeez_vertex(@builtin(vertex_index) index: u32) -> SvjeezVarying {
  let corner = vec2f(f32((index << 1u) & 2u), f32(index & 2u));

  return SvjeezVarying(vec4f(corner * 2 - 1, 0, 1), vec2f(corner.x, 1 - corner.y));
}

@fragment fn svjeez_fragment(vertex: SvjeezVarying) -> @location(0) vec4f {
  return shade(vertex.uv, svjeez_inputs);
}
